def _is_gibberish(low: str) -> bool:
    """Kachra/noise input (fdsf, xyzqwerty...) — asli lafz ya common word nahi milte.
    Clean vocabulary (common English + Roman Urdu) use karta hai, NOT learned corpus,
    taake polluted memory gibberish detection ko break na kare."""
    tk = re.findall(r"[a-z]{2,}", low)
    if not tk:
        return True
    clean = _STOP | _ROMAN_URDU_COMMON
    known = sum(1 for t in tk if t in clean)
    # heuristic: 4+ consecutive consonants = keyboard smash (xyzqwertyuiop)
    smash = False
    for t in tk:
        cons_run = 0
        for c in t:
            if c in "aeiou":
                cons_run = 0
            else:
                cons_run += 1
                if cons_run >= 4:
                    smash = True
                    break
        if smash:
            break
    if smash:
        return True
    return known / len(tk) < 0.35

