def _match_social(token: str) -> "tuple[str|None, str|None]":
    """Ek token ko social base se match karo (fold2 + fold1 + compound byebye)."""
    cands = {token}
    f1 = fold1(token)
    if f1 != token:
        cands.add(f1)
    # compound "byebye"/"byebyebye" bhi farewell hai
