"""
🤝 helper_brain.py — TEESRA DIMAGH (GENONE-HELPER ~5.1M params, dh560)

User qanoon: "2 more brains each of 5M — one for HELPING main brain +
thinking engine to give good answers, second for VERIFYING research answers;
dono main brain se CONNECT; main brain 7M."

Helper brain ka kaam:
  • jab master (7M) ka khud-soch gate FAIL ho → helper ek dafa khud-sample
    karta hai ("1 dafa hor socho" courtesy) → 'helper-soch' jawab
  • master + aqal-core (model/aqal.py) ke candidates ko dosri ray deta hai
  • bridge: 250k bio-neuron tissues (core/hub) + deep-brain (dh620) network

Checkpoint: model/genhelper_*.npz  (tarbiyat: scripts\\train_master.py 6000 --helper)
No API, no cloud, no AI-model connection — pure NumPy.
"""

import glob
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
if ROOT not in sys.path:
    sys.path.insert(0, ROOT)
os.chdir(ROOT)

_HELPER = {"checked": False, "path": None}


def checkpoint():
    """SAB se naya helper checkpoint (genhelper_*.npz, chat.npz chor kar)."""
    if not _HELPER["checked"]:
        _HELPER["checked"] = True
        try:
            from model.generate import CKPT_DIR
            cands = []
            for p in glob.glob(os.path.join(CKPT_DIR, "genhelper_*.npz")):
                base = os.path.basename(p)
                if base.startswith("genhelper_chat"):
                    continue
                cands.append(p)
            cands.sort(key=os.path.getmtime, reverse=True)
            _HELPER["path"] = cands[0] if cands else None
        except Exception:
            _HELPER["path"] = None
    return _HELPER["path"]


def refresh():
    """Naye checkpoint ke baad dobara dekho."""
    _HELPER["checked"] = False
    return checkpoint()


def params_estimate(vocab: int = 80) -> int:
    """LSTMBrain param-count (helper: dh=560) — 16dh^2 + 2*vocab*dh."""
    dh = 560
    return 16 * dh * dh + 2 * vocab * dh


def assist(prompt, notes=None, temperature: float = 0.5, max_new: int = 130):
    """MASTER ke jawab kharab aya? HELPER ek dafa khud sochta hai.
    Return: (text) ya None (fail / helper checkpoint nahi). Sab quality-guards."""
    ck = checkpoint()
    if not ck:
        return None
    try:
        from model.generate import (_load_model, _clean, _no_citation,
                                    _quality, _relevance)
        tok, brain = _load_model(ck)
        p2 = ("\n" + "\n".join((notes or [])[:2]) + "\n") if notes else "\n"
        out = brain.sample(p2, tok, max_new=max_new,
                           temperature=min(0.85, temperature * 1.1))
        c = _clean(out)
        if c and _no_citation(c) and len(c) >= 24:
            sc = _quality(c) + _relevance(prompt, c)
            if _quality(c) >= 2.2 and sc >= 2.6:
                return c
    except Exception:
        return None
    return None


def status():
    """Hub ke liye: helper-brain dictionary."""
    ck = checkpoint()
    return {"on": bool(ck), "checkpoint": os.path.basename(ck) if ck else None,
            "params": "%s (~5.1M, dh560) — master-ka-madadgar" % f"{params_estimate():,}",
            "bridge": "master(7M)+aqal-core+deep(6.25M)+verify(5.1M)+250k bio-neurons"}


if __name__ == "__main__":
    try:
        sys.stdout.reconfigure(encoding="utf-8")
    except Exception:
        pass
    print("🤝 HELPER brain:", status())
    r = assist("ilm kya hai")
    print("sample:", (r or "(helper checkpoint nahi / fail)")[:160])

"""
🔎 verify_brain.py — CHAUTHA DIMAGH (GENONE-VERIFY ~5.1M params, dh560)

User qanoon: "2 more brains each of 5M — one HELPS main brain give good
answers, SECOND VERIFIES research answers ... jo cheez isse nahi aati wo
google live se search kare aur VERIFY bhi kare phir jawab de."

Verifier brain ka kaam (research-jawab ki TASDEEQ — 3-layer):
  1. PERPLEXITY CHECK   : jawab ke chars verifier-LSTM me dal kar dekho —
     corpus-trained model ke liye "ajaib/ghair-mumkin" text = high perplexity
     → reject. (real NumPy forward pass, no API)
  2. SOURCE-CONSISTENCY : research-cache (liveresearch.txt) ke usi sawal ke
     page-snippet se keyword-overlap — jawab page se juda ho to PASS.
  3. ARTIFACT-GUARDS    : nakli ayat/hadith citation + junk-quality checks
     (fabrication net — khud-soch jaisa hi sakht).

Verdict: {"ok": True/False/None, "score": 0..1, "reason": str}
None = verifier checkpoint nahi (fail-safe: research jawab waisehi jata hai
magar meta me 'unverified' mark hota hai).

Checkpoint: model/genverify_*.npz (tarbiyat: scripts\\train_master.py 6000 --verify)
"""

import glob
import os
import re
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
if ROOT not in sys.path:
    sys.path.insert(0, ROOT)
os.chdir(ROOT)

_VERIFY = {"checked": False, "path": None}


def checkpoint():
    """SAB se naya verifier checkpoint (genverify_*.npz)."""
    if not _VERIFY["checked"]:
        _VERIFY["checked"] = True
        try:
            from model.generate import CKPT_DIR
            cands = []
            for p in glob.glob(os.path.join(CKPT_DIR, "genverify_*.npz")):
                base = os.path.basename(p)
                if base.startswith("genverify_chat"):
                    continue
                cands.append(p)
            cands.sort(key=os.path.getmtime, reverse=True)
            _VERIFY["path"] = cands[0] if cands else None
        except Exception:
            _VERIFY["path"] = None
    return _VERIFY["path"]


def refresh():
    _VERIFY["checked"] = False
    return checkpoint()


def params_estimate(vocab: int = 80) -> int:
    dh = 560
    return 16 * dh * dh + 2 * vocab * dh


# ----------------------------------------------------------------------
# layer 1: perplexity (verifier LSTM se jawab ki "mumkinat" janch)
# ----------------------------------------------------------------------
def _perplexity(text: str, tok, brain) -> float:
    """Char-level avg log-prob (higher=better). Guarded, fast (256 chars)."""
    try:
        ids = tok.encode(text[:256])
        if len(ids) < 4:
            return 0.0
        probs, _c = brain.forward_sequence(ids[:-1])
        lp = 0.0
        for t, p in enumerate(probs):
            tgt = ids[t + 1]
            lp += max(-20.0, float(p[tgt]))
        return lp / max(1, len(probs))
    except Exception:
        return 0.0


# ----------------------------------------------------------------------
# layer 2: research-cache consistency
# ----------------------------------------------------------------------
def _cache_consistency(prompt: str, answer: str) -> float:
    """liveresearch.txt cache me isi sawal ka snippet mile to overlap 0..1."""
    try:
        from model.generate import BIG   # data/corpus_big
        path = os.path.join(BIG, "liveresearch.txt")
        if not os.path.exists(path):
            return 0.0
        with open(path, encoding="utf-8", errors="ignore") as f:
            lines = f.read().split("\n")
        # aakhri 40 "Sawal:" blocks dekho (naya research sab se upar hota hai)
        blocks, cur_q, cur_a = [], None, []
        for ln in lines[-400:]:
            s = ln.strip()
            if s.lower().startswith("sawal:"):
                if cur_q is not None:
                    blocks.append((cur_q, " ".join(cur_a)))
                cur_q, cur_a = s[6:].strip(), []
            elif s.lower().startswith("jawab:") and cur_q is not None:
                cur_a.append(s[6:].strip())
            elif cur_q is not None and s:
                cur_a.append(s)
        if cur_q is not None:
            blocks.append((cur_q, " ".join(cur_a)))
        # sawal-match: token overlap
        qw = set(re.findall(r"[a-z]{3,}", prompt.lower())) - {"kya", "hai", "what", "the"}
        best = 0.0
        for q, a in blocks:
            qset = set(re.findall(r"[a-z]{3,}", q.lower()))
            if not qset:
                continue
            ov = len(qw & qset) / max(1, len(qw | qset))
            if ov > best:
                aw = set(re.findall(r"[a-z]{3,}", a.lower()))
                best = ov * (len(qw & aw) / max(1, len(qw))) if qw else 0.0
        return round(min(1.0, best), 3)
    except Exception:
        return 0.0


# ----------------------------------------------------------------------
# layer 3: artifact guards (nakli citation / kachra)
# ----------------------------------------------------------------------
def _artifacts_ok(answer: str) -> bool:
    try:
        from model.generate import _no_citation, _quality
        if not answer or len(answer) < 20:
            return False
        if not _no_citation(answer):
            return False
        if _quality(answer) < 1.5:
            return False
        return True
    except Exception:
        return len(answer or "") >= 20


# ----------------------------------------------------------------------
# MAIN VERIFY
# ----------------------------------------------------------------------
def verify(prompt: str, answer: str, page: str = None) -> dict:
    """Research jawab ki tasdeeq. page = (optional) raw research snippet."""
    ck = checkpoint()
    checks = {}
    # 3) artifacts (hamesha)
    checks["artifacts"] = _artifacts_ok(answer)
    if not checks["artifacts"]:
        return {"ok": False, "score": 0.0,
                "reason": "fabrication/junk guards fail", "checks": checks}

    # 2) source-consistency (cache ya page)
    src = 0.0
    if page:
        qw = set(re.findall(r"[a-z]{3,}", (prompt or "").lower())) - {"kya", "hai", "what"}
        aw = set(re.findall(r"[a-z]{3,}", (answer or "").lower()))
        pw = set(re.findall(r"[a-z]{3,}", (page or "").lower()))
        if qw and aw and pw:
            src = round(len((qw | aw) & pw) / max(1, len(qw | aw)), 3)
    else:
        src = _cache_consistency(prompt, answer)
    checks["source_consistency"] = src

    # 1) perplexity (agar checkpoint hai)
    ppl = None
    if ck:
        try:
            from model.generate import _load_model
            tok, brain = _load_model(ck)
            ppl = _perplexity(answer, tok, brain)
        except Exception:
            ppl = None
    checks["perplexity"] = ppl

    # decision
    score = 0.4 * src + (0.6 * min(1.0, max(0.0, ppl)) if ppl is not None
                         else 0.6 * 0.5)
    ok = score >= 0.45
    reason = ("tasdeeq: src=%.2f ppl=%s → %s"
              % (src, ("%.2f" % ppl) if ppl is not None else "n/a",
                 "PASS" if ok else "KAMZOR"))
    return {"ok": ok, "score": round(score, 3), "reason": reason, "checks": checks}


def status():
    """Hub ke liye: verifier-brain dictionary."""
    ck = checkpoint()
    return {"on": bool(ck), "checkpoint": os.path.basename(ck) if ck else None,
            "params": "%s (~5.1M, dh560) — research-ka-tasdeeq-kar" % f"{params_estimate():,}",
            "bridge": "live-research chain + master(7M) + helper(5.1M) + deep(6.25M)"}


if __name__ == "__main__":
    try:
        sys.stdout.reconfigure(encoding="utf-8")
    except Exception:
        pass
    print("🔎 VERIFY brain:", status())
    r = verify("photosynthesis kya hai",
               "Photosynthesis is the process by which plants make food using sunlight.")
    print("verify:", r)

