def _perplexity(text: str, tok, brain) -> float:
    """Char-level avg LOG-prob (asli log — pehle ghalati se raw probability
    thi). Range ~ -4..-1; 0 = khaali/na-tasdeeq-shuda. Guarded, fast (256)."""
    try:
