def _unredirect(u: str):
    """DDG/Google redirect-links ('/l/?uddg=…', '/url?q=…') → asli URL."""
    if not u:
        return None
    if "uddg=" in u:
        m = re.search(r"uddg=([^&]+)", u)
        if m:
            u = urllib.parse.unquote(m.group(1))
    elif u.startswith("/url?"):
        m = re.search(r"[?&]q=([^&]+)", u)
        if m:
            u = urllib.parse.unquote(m.group(1))
    if u.startswith("//"):
        u = "https:" + u
    return u if u.startswith("http") else None


