.btn.line:hover { border-color: var(--gold); color: var(--gold); }
.btn:disabled { opacity: .45; cursor: not-allowed; }
.status { margin-top: 18px; color: var(--dim); font-size: .95em; }

/* sections */
.sec { padding: 54px 0; }
.sec.dark { background: var(--panel); border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border); }
h2 { font-size: 1.7em; margin-bottom: 14px; }
h3 { color: var(--gold); margin: 20px 0 8px; }
.grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 16px; }
