.msg.user { background: #1f5c46; align-self: flex-end; }
.msg.ai { background: #182b23; border: 1px solid var(--border); align-self: flex-start; }

footer { background: var(--panel); border-top: 1px solid var(--border);
  text-align: center; padding: 26px 0; color: var(--dim); font-size: .95em; }
@media (max-width: 640px) {
  .hero h1 { font-size: 2.1em; }
  nav a { margin-left: 10px; }
