/* HMHZ · GenOne website — sirf LOCAL baatein (koi external service nahi):
   - /health same-origin check (tab jab ye site GenOne ke apne server se khuli ho)
   - demo chat → POST /v1/chat (L6 headers: key + ts + nonce) — sab local */

(function () {
  "use strict";
  var $ = function (id) { return document.getElementById(id); };

  /* ---------- health check (same-origin only — graceful fallback) ---------- */
  var healthLine = $("health-line");
  function nonce() {
    try { return Array.from(crypto.getRandomValues(new Uint8Array(8)))
      .map(function (b) { return b.toString(16).padStart(2, "0"); }).join(""); }
    catch (e) { return "w-" + Date.now().toString(36); }
  }
  function ts() { return String(Math.floor(Date.now() / 1000)); }

  function checkHealth() {
    if (!healthLine) return;
    fetch("/health", {
      headers: { "X-GenOne-Key": (localStorage.getItem("genone_key") || "-"),
                 "X-GenOne-Ts": ts(), "X-GenOne-Nonce": nonce() }
    }).then(function (r) {
      if (r.ok) {
        healthLine.innerHTML = "🟢 <b class='gold'>GenOne zinda hai</b> — ye website GenOne ke " +
          "apne local server se chal rahi hai (demo chalu).";
        var send = $("demo-send");
        if (send) send.disabled = false;
      } else {
        healthLine.textContent = "🟡 Website static mode me hai — demo ke liye GenOne locally chalao (server on).";
      }
    }).catch(function () {
      healthLine.textContent = "🟡 Static mode — ye file kahin bhi khul sakti hai; dimagh hamesha local rehta hai.";
    });
  }

  /* ---------- demo chat ---------- */
  function addMsg(cls, text) {
    var log = $("demo-chat");
    if (!log) return;
    var d = document.createElement("div");
    d.className = "msg " + cls;
    d.textContent = text;
    log.appendChild(d);
    log.scrollTop = log.scrollHeight;
  }

  function send() {
    var q = $("demo-q").value.trim();
    var key = ($("demo-key").value || "").trim() || localStorage.getItem("genone_key") || "";
    if (!q) return;
    if (key) { try { localStorage.setItem("genone_key", key); } catch (e) {} }
    addMsg("user", q);
    $("demo-q").value = "";
    addMsg("ai", "🤔 soch raha hai… (yaad → khud-soch → page-parhi? → tasdeeq)");
    fetch("/v1/chat", {
      method: "POST",
      headers: { "Content-Type": "application/json",
                 "X-GenOne-Key": key, "X-GenOne-Ts": ts(), "X-GenOne-Nonce": nonce() },
      body: JSON.stringify({ prompt: q })
    }).then(function (r) { return r.json().then(function (j) { return { code: r.status, j: j }; }); })
      .then(function (o) {
        // aakhri "soch raha hai…" hatao
        var log = $("demo-chat");
        if (log && log.lastChild) log.removeChild(log.lastChild);
        if (o.code === 200) addMsg("ai", o.j.answer || "(khali jawab)");
        else addMsg("ai", "⚠ " + (o.j.error || ("HTTP " + o.code)) +
          "  (key/ts/nonce check karen — L6-HMHZ guard)");
      })
      .catch(function () {
        var log = $("demo-chat");
        if (log && log.lastChild) log.removeChild(log.lastChild);
        addMsg("ai", "⚠ GenOne server tak pahunch nahi — kya 'server on' chala hai? (sab local hai, koi cloud nahi)");
      });
  }

  document.addEventListener("DOMContentLoaded", function () {
    checkHealth();
    var send_ = $("demo-send");
    if (send_) send_.addEventListener("click", send);
    var q = $("demo-q");
    if (q) q.addEventListener("keydown", function (e) { if (e.key === "Enter") send(); });
  });
})();

