"""
👤 server/accounts.py — GENONE ULTRA API ke PER-USER ACCOUNTS (100% local)

User qanoon (saaf-saf): "har bande ki APNI API hogi — GenOne Ultra jisse wo
copy kar paye aur usse koi bhi kaam karwa paye. API is se LINKED hai —
GenOne Ultra API. NO any platform API of the world."

  - SIGN-UP / SIGN-IN: email (Gmail bhi) + password — SAB KUCH ISI PC par
    (data/genone_users.json). ⚠️ Google/Facebook waala asli OAuth JAAN-BOOJH
    kar NAHI hai: asli Google sign-in ko Google ki OAuth API chahiye — aur
    user ka pakka qanoon hai "no any platform API of the world". Is liye ye
    LOCAL sign-in hai: aap apna Gmail/Email + apna password yahin rakhte hain
    — Google ko koi call NAHI jata, koi platform API NAHI lagti.
  - HAR BANDE KI APNI KEY: sign-in par `gk_…` key milti hai — wahi uski
    GenOne Ultra API key hai (X-GenOne-Key header me lagti hai). Copy kar ke
    koi bhi kaam karwa sakta hai (chat/health/info — sab isi local dimagh se).
  - PASSWORD KABHI PLAIN NAHI: PBKDF2-HMAC-SHA256 (200k rounds, 16B namak).
  - USAGE: har key apni request-ginti + aakhri-istemaal yaad rakhti hai.

API:
    signup(email, password)  -> dict (ok) | dict (error + code)
    signin(email, password)  -> dict (ok) | dict (error + code)
    valid_key(key)           -> bool (guard.py L6 call karta hai)
    me(key)                  -> dict | None  (email/requests/created)
    bump(key)                -> usage +1 (server chat pass par)
"""
import hashlib
import json
import os
import re
import secrets
import time

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
USERS_PATH = os.path.join(ROOT, "data", "genone_users.json")
_PBKDF2_ROUNDS = 200_000
_EMAIL_RX = re.compile(r"^[^@\s]+@[^@\s]+\.[A-Za-z]{2,}$")
_lock = __import__("threading").Lock()


# ------------------------------------------------------------ store
def _load():
    try:
        with open(USERS_PATH, encoding="utf-8") as f:
            d = json.load(f)
        if isinstance(d, dict) and isinstance(d.get("users"), dict):
            return d
    except Exception:
        pass
    return {"users": {}, "note": "GenOne Ultra API per-user accounts "
                                 "(100% local — no platform API)"}


def _save(d):
    os.makedirs(os.path.dirname(USERS_PATH), exist_ok=True)
    tmp = USERS_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(d, f, indent=1)
    os.replace(tmp, USERS_PATH)          # atomic — half-written kabhi nahi


def _hash_pw(password: str, salt: bytes) -> str:
    return hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"),
                               salt, _PBKDF2_ROUNDS).hex()


def _check_email(email: str) -> bool:
    return bool(_EMAIL_RX.match(str(email or "").strip()))


# ------------------------------------------------------------ sign-up/in
def signup(email: str, password: str) -> dict:
    """Naya account → bande ki APNI GenOne Ultra API key (foran copy-ready)."""
    email = str(email or "").strip().lower()
    password = str(password or "")
    if not _check_email(email):
        return {"error": "email ghalat — misal: naam@gmail.com", "code": 400}
    if len(password) < 6:
        return {"error": "password kam-az-kam 6 heruf ka rakho", "code": 400}
    with _lock:
        d = _load()
        if email in d["users"]:
            return {"error": "ye email pehle se hai — Sign-in karo",
                    "code": 409}
        salt = secrets.token_bytes(16)
        key = "gk_" + secrets.token_hex(24)     # bande ki APNI GenOne key
        d["users"][email] = {
            "salt": salt.hex(),
            "pw": _hash_pw(password, salt),
            "key": key,
            "created": time.strftime("%Y-%m-%d %H:%M:%S"),
            "requests": 0,
            "last_used": "",
        }
        _save(d)
    return {"ok": True, "email": email, "key": key,
            "note": "ye AAPKI GenOne Ultra API key hai — copy kar lo "
                    "(X-GenOne-Key header). Kisi platform ki API nahi — "
                    "seedha GenOne Ultra Brain (local) se juri hai."}


def signin(email: str, password: str) -> dict:
    """Sign-in → wahi APNI key wapas (nayi nahi banti — account linked)."""
    email = str(email or "").strip().lower()
    password = str(password or "")
    with _lock:
        d = _load()
        u = d["users"].get(email)
        if not u:
            return {"error": "ye email registered nahi — pehle Nayi API lein",
                    "code": 403}
        try:
            ok = secrets.compare_digest(
                _hash_pw(password, bytes.fromhex(u["salt"])), u["pw"])
        except Exception:
            ok = False
        if not ok:
            return {"error": "password ghalat", "code": 403}
        u.setdefault("requests", 0)
        _save(d)
    return {"ok": True, "email": email, "key": u["key"],
            "created": u.get("created", ""),
            "requests": u.get("requests", 0),
            "note": "sign-in OK — ye AAPKI GenOne Ultra API key hai "
                    "(X-GenOne-Key). 100% local — no platform API."}


# ------------------------------------------------------------ keys/usage
def valid_key(key: str) -> bool:
    """guard.py (L6): kya ye key kisi bande ki APNI GenOne key hai?"""
    if not key or not str(key).startswith("gk_"):
        return False
    try:
        with _lock:
            d = _load()
        for u in d["users"].values():
            if secrets.compare_digest(str(key), str(u.get("key", ""))):
                return True
    except Exception:
        pass
    return False


def bump(key: str):
    """Har kamiyab API-request par bande ki ginti +1 (asli istehsaal)."""
    if not key:
        return
    try:
        with _lock:
            d = _load()
            for u in d["users"].values():
                if secrets.compare_digest(str(key), str(u.get("key", ""))):
                    u["requests"] = int(u.get("requests", 0)) + 1
                    u["last_used"] = time.strftime("%Y-%m-%d %H:%M:%S")
                    _save(d)
                    return
    except Exception:
        pass


def me(key: str):
    """/v1/auth/me — bande ki apni jaankari (ya None)."""
    if not key:
        return None
    try:
        with _lock:
            d = _load()
        for email, u in d["users"].items():
            if secrets.compare_digest(str(key), str(u.get("key", ""))):
                return {"email": email, "key": key,
                        "created": u.get("created", ""),
                        "requests": u.get("requests", 0),
                        "last_used": u.get("last_used", ""),
                        "api": "GenOne Ultra API v1 (apni key, 100% local)"}
    except Exception:
        pass
    return None


def stats():
    """Kitne bande apni GenOne key le chuke (dashboard ke liye)."""
    try:
        with _lock:
            d = _load()
        return {"users": len(d["users"]), "file": "data/genone_users.json"}
    except Exception:
        return {"users": 0}

