/* ☪ GenOne Ultra Brain — download-portal style (emerald + gold, dark) */
:root{
  --bg:#0b1512; --panel:#102618; --panel2:#0e211a; --line:#1e3c30;
  --gold:#d9b45b; --gold2:#f0d492; --em:#2fbf8f; --em2:#1f8f6c;
  --txt:#e8f2ec; --dim:#9db8ab; --red:#e06a5a;
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{background:var(--bg);color:var(--txt);
  font-family:"Segoe UI",Tahoma,Arial,sans-serif;line-height:1.6}
.wrap{max-width:1060px;margin:0 auto;padding:0 22px}
h2{font-size:1.7rem;margin-bottom:18px;color:var(--gold2)}
h3{margin-bottom:8px}
h4{margin-bottom:4px}
code{background:#0a1b14;border:1px solid var(--line);border-radius:6px;
  padding:1px 7px;font-size:.9em;color:var(--gold2)}
pre{background:#0a1b14;border:1px solid var(--line);border-radius:10px;
  padding:14px;overflow:auto;font-size:.85rem;color:#cfe9dd}
a{color:var(--em)}

/* ── header ── */
.top{position:sticky;top:0;z-index:9;background:rgba(11,21,18,.92);
  backdrop-filter:blur(8px);border-bottom:1px solid var(--line)}
.nav{display:flex;align-items:center;justify-content:space-between;height:62px}
.brand{display:flex;gap:10px;align-items:center;font-size:1.15rem;font-weight:600}
.brand b{color:var(--gold)}
.moon{color:var(--gold);font-size:1.3rem}
.nav a{color:var(--dim);text-decoration:none;margin-left:20px;font-size:.93rem}
.nav a:hover{color:var(--gold2)}

/* ── hero ── */
.hero{padding:84px 0 66px;text-align:center;
  background:radial-gradient(700px 340px at 50% -60px,#17352a 0%,var(--bg) 70%)}
.pill{display:inline-block;border:1px solid var(--em2);color:var(--em);
  border-radius:999px;padding:5px 16px;font-size:.8rem;letter-spacing:.6px}
.hero h1{font-size:3.1rem;margin:18px 0 10px;letter-spacing:.5px}
.hero h1 span{color:var(--gold)}
.lead{color:var(--dim);max-width:640px;margin:0 auto;font-size:1.06rem}
.lead b{color:var(--txt)}
.hero-btns{margin:26px 0 34px;display:flex;gap:12px;justify-content:center;flex-wrap:wrap}
.hero-stats{display:flex;gap:26px;justify-content:center;flex-wrap:wrap;color:var(--dim)}
.hero-stats b{display:block;font-size:1.25rem;color:var(--gold2)}
.hero-stats span{font-size:.8rem}

/* ── buttons ── */
.btn{display:inline-block;border-radius:12px;padding:11px 22px;font-size:.98rem;
  text-decoration:none;cursor:pointer;border:1px solid transparent;
  transition:transform .12s,box-shadow .12s}
.btn:hover{transform:translateY(-1px)}
.btn.gold{background:linear-gradient(180deg,var(--gold),#c49a3f);color:#141b14;
  font-weight:700;box-shadow:0 6px 18px rgba(217,180,91,.22)}
.btn.ghost{border-color:var(--em2);color:var(--em)}
.btn.big{font-size:1.12rem;padding:14px 30px}
.btn:disabled{opacity:.5;cursor:wait;transform:none}

/* ── sections/cards ── */
.sec{padding:58px 0}
.sec.alt{background:var(--panel2);border-block:1px solid var(--line)}
.card{background:var(--panel);border:1px solid var(--line);border-radius:16px;
  padding:22px;margin-bottom:14px}
.card.warn{border-color:#6b4a2a;background:#1c1712;color:#e8d5b0}
.note{color:var(--dim);font-size:.9rem;margin-top:12px}
.badges{margin-top:10px;display:flex;gap:8px;flex-wrap:wrap}
.badge{border:1px solid var(--em2);color:var(--em);border-radius:999px;
  padding:3px 12px;font-size:.78rem}

.dl-main{display:flex;gap:20px;align-items:center;flex-wrap:wrap}
.dl-main>div:nth-child(2){flex:1;min-width:260px}
.dl-icon{font-size:2.6rem}
.dl-card .btn{white-space:nowrap}

/* ── steps ── */
.steps{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:14px}
.step{display:flex;gap:14px;background:var(--panel);border:1px solid var(--line);
  border-radius:14px;padding:16px}
.step span{flex:0 0 34px;height:34px;border-radius:50%;background:var(--gold);
  color:#141b14;font-weight:800;display:flex;align-items:center;justify-content:center}
