.form input{background:#0a1b14;border:1px solid var(--line);border-radius:10px;
  padding:11px 14px;color:var(--txt);font-size:.96rem;outline:none}
.form input:focus{border-color:var(--gold)}
.form-btns{display:flex;gap:10px;flex-wrap:wrap;margin-top:4px}
.key-list{display:flex;flex-direction:column;gap:8px;margin:12px 0}
.key-item{display:flex;gap:10px;align-items:center;background:#0a1b14;
  border:1px solid var(--line);border-radius:10px;padding:10px 12px}
.key-item code{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.count{color:var(--dim);font-size:.85rem;font-weight:400}
.usage{margin-top:14px}
.usage h4{color:var(--gold2)}
