$API = "https://api.github.com"
$local = "D:\DigitalBrain\web\sitemap.xml"
$repos = @("noity0/hemomemo-ai", "noity0/noity0.github.io")

foreach ($r in $repos) {
  $sha = $null
  try {
    $ex = Invoke-RestMethod -Uri "$API/repos/$r/contents/sitemap.xml" -Headers $H
    $sha = $ex.sha
  } catch {}
  $b64 = [Convert]::ToBase64String([IO.File]::ReadAllBytes($local))
  $fb = @{ message = "sitemap: exact owner version with xhtml and priority"; content = $b64 }
