# _final_checks.ps1 — uploader band + clean build + confirm
$patU = '_upload' + '_zip.ps1'
Get-CimInstance Win32_Process -Filter "Name='pwsh.exe'" |
  Where-Object { $_.ProcessId -ne $PID -and $_.CommandLine -and $_.CommandLine.Contains($patU) } |
  ForEach-Object { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue; "UPLOADER-KILLED pid=$($_.ProcessId)" }
$patR = 'Invoke-RestMethod.*uploads.github.com'
"--- adhoora asset-upload ka python/pwsh koi nahi chahiye ---"

$gh = "C:\Program Files\GitHub CLI\gh.exe"
$tok = (& $gh auth token).Trim()
$H = @{ Authorization = "token $tok"; Accept = "application/vnd.github+json"; "User-Agent" = "hemomemo-deploy" }
$API = "https://api.github.com"

# dono repos par EK saaf build trigger + built tak intezar
foreach ($r in @("noity0/hemomemo-ai", "noity0/noity0.github.io")) {
  try {
    Invoke-RestMethod -Method Post -Uri "$API/repos/$r/pages/builds" -Headers $H | Out-Null
    "TRIGGERED: $r"
  } catch { "TRIGGER-SKIP: $r" }
  $ok = $false
  for ($i = 0; $i -lt 25; $i++) {
    Start-Sleep 6
    try {
      $b = Invoke-RestMethod -Uri "$API/repos/$r/pages/builds/latest" -Headers $H
      "build $r [$i]: $($b.status)"
      if ($b.status -eq "built") { $ok = $true; break }
      if ($b.status -eq "errored") { break }
    } catch { }
  }
  "BUILD-RESULT ${r}: $ok"
}

# release-asset ki mojooda halat (record ke liye)
$rel = Invoke-RestMethod -Uri "$API/repos/noity0/hemomemo-ai/releases/tags/v4.2.0-people" -Headers $H
"ASSETS-ABHI: " + ($rel.assets | ForEach-Object { "$($_.name)=$($_.size)=$($_.state)" }) -join ", "
"FINAL-CHECKS-DONE"

