# _netlify_deploy.ps1 — Netlify par hemomemo-ai site create + deploy (non-interactive)
$ErrorActionPreference = "Continue"
$npx = "npx"

"=== 1. account slug ==="
$accRaw = & $npx --yes netlify-cli api listAccountsForUser 2>$null | Out-String
$acc = $accRaw | ConvertFrom-Json
$slug = $acc[0].slug
"SLUG: $slug"

"=== 2. site create (fallback-naam ke sath) ==="
$site = $null
foreach ($nm in @("hemomemo-ai", "hemomemoai", "hemomemo-ai-app", "hemomemo-ultra")) {
  "TRY-NAME: $nm"
  $body = ('{"name": "' + $nm + '"}')
  $raw = & $npx --yes netlify-cli api createSite --data $body 2>$null | Out-String
  $site = $null
  try { $site = $raw | ConvertFrom-Json } catch {}
  if ($site -and $site.id) { "SITE-BANA: $($site.name) | id=$($site.id) | url=$($site.ssl_url)"; break }
  else { "  (nama-mojood nahi ya masla — agla naam)" }
}
if (-not $site -or -not $site.id) { "SITE-FAIL — band"; exit 1 }

"=== 3. deploy (web_surge → prod) ==="
& $npx --yes netlify-cli deploy --site $site.id --dir "D:\DigitalBrain\web_surge" --prod 2>&1 |
  Select-Object -Last 12

"=== 4. verify ==="
