"""HEMOMO MEMORY - yaad-dasht ka dil (100% local, koi API nahi).

Do hisse:
1) EpisodicStore  - guzri hui baatein yaad rakhna (JSONL, aap ke PC par)
2) KnowledgeRetrieval - Sawal:/Jawab: corpus se sab-se-mutaaliq jawab dhoondna

Koi cloud, koi embed-API, koi doosra model - NAHI. Sirf token-overlap +
recency - Hemomemo ka apna apna tareeqa.
"""
from __future__ import annotations

import json
import os
import re
import threading
import time
from typing import Callable, Iterable, List, Optional, Tuple

_WORD = re.compile(r"[a-z0-9]+", re.UNICODE)

def _tokens(text: str) -> List[str]:
    return _WORD.findall((text or "").lower())

def _overlap(query_toks: List[str], cand_toks: List[str]) -> float:
    if not query_toks or not cand_toks:
        return 0.0
    q = set(query_toks)
    c = set(cand_toks)
    if not q or not c:
        return 0.0
    hit = len(q & c)
    return hit / max(1.0, float(len(q)))  # kitne sawal-ke-lafz milay


class EpisodicStore:
    """Har baat (sawal+jawab) ko PC par JSONL me mehfooz karta hai.

    File: <data_dir>/memory/episodic.jsonl  (har line = ek JSON record)
    Recall: token-overlap + recency-boost (nayi yaad zyada wazni).
    """

    def __init__(self, data_dir: str, max_recall: int = 5) -> None:
        self.data_dir = data_dir
        self.mem_dir = os.path.join(data_dir, "memory")
        os.makedirs(self.mem_dir, exist_ok=True)
        self.path = os.path.join(self.mem_dir, "episodic.jsonl")
        self.max_recall = max_recall
        self._lock = threading.Lock()

    # --- yaddasht likhna ---
    def remember(self, user: str, bot: str, tag: str = "chat") -> None:
        rec = {
            "ts": time.time(),
            "iso": time.strftime("%Y-%m-%d %H:%M:%S"),
            "tag": tag,
            "user": (user or "")[:2000],
            "bot": (bot or "")[:4000],
        }
        line = json.dumps(rec, ensure_ascii=False)
        with self._lock:
            with open(self.path, "a", encoding="utf-8") as fh:
                fh.write(line + "\n")

    # --- yaddasht parhna ---
    def _iter(self) -> Iterable[dict]:
        if not os.path.exists(self.path):
            return []
        out = []
        try:
            with open(self.path, "r", encoding="utf-8") as fh:
                for line in fh:
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        out.append(json.loads(line))
                    except Exception:
                        continue
        except OSError:
            return []
        return out

    def recall(self, query: str, k: Optional[int] = None) -> List[dict]:
        """Sab-se-mutaaliq purani baatein (nayi wali pehle wazni)."""
        k = k or self.max_recall
        qt = _tokens(query)
        now = time.time()
        scored: List[Tuple[float, dict]] = []
        for rec in self._iter():
            toks = _tokens(rec.get("user", "") + " " + rec.get("bot", ""))
            base = _overlap(qt, toks)
            age_h = max(0.0, (now - float(rec.get("ts", now))) / 3600.0)
            recency = 1.0 / (1.0 + age_h / 24.0)  # 24-ghante halke boost
            scored.append((base * 2.0 + recency * 0.3, rec))
        scored.sort(key=lambda p: p[0], reverse=True)
        return [rec for sc, rec in scored[:k] if sc > 0.0]

    def session_summary(self, last_n: int = 20) -> dict:
        recs = list(self._iter())[-last_n:]
        return {
            "total_memories": len(list(self._iter())),
            "shown": len(recs),
            "items": recs,
        }

    def forget_all(self) -> int:
        """Poora episodic-yad saaf (user ki marzi se)."""
        n = len(list(self._iter()))
        with self._lock:
            try:
                os.remove(self.path)
            except OSError:
                pass
        return n


class KnowledgeRetrieval:
    """corpus_big ke Sawal:/Jawab: pairs me se mutaliq ilm nikalna."""

    def __init__(self, corpus_dir: str, files: Optional[List[str]] = None) -> None:
        self.corpus_dir = corpus_dir
        self.files = files or ["games_knowledge.txt", "coding_knowledge.txt",
                               "coding_deep_master.txt", "harvest_live.txt"]
        self._pairs: List[Tuple[str, str, List[str]]] = []
        self._loaded_from: Optional[str] = None
        self._lock = threading.Lock()

    def _load(self) -> None:
        with self._lock:
            if self._loaded_from == self.corpus_dir:
                return
            pairs: List[Tuple[str, str, List[str]]] = []
            for fn in self.files:
                fp = os.path.join(self.corpus_dir, fn)
                if not os.path.isfile(fp):
                    continue
                try:
                    raw = open(fp, "r", encoding="utf-8", errors="ignore").read()
                except OSError:
                    continue
                qs = re.findall(r"Sawal:\s*(.+?)\s*\nJawab:\s*(.+?)(?=\n\S|\Z)",
                                raw, re.DOTALL)
                for q, a in qs:
                    q1 = " ".join(str(q).split())
                    a1 = " ".join(str(a).split())[:1200]
                    if q1 and a1:
                        pairs.append((q1, a1, _tokens(q1 + " " + a1)))
            self._pairs = pairs
            self._loaded_from = self.corpus_dir

    def search(self, query: str, k: int = 3) -> List[Tuple[str, str, float]]:
        """(sawal, jawab, score) - sab-se-mutaaliq pehle."""
        self._load()
        qt = _tokens(query)
        if not qt:
            return []
        scored = []
        for q, a, toks in self._pairs:
            sc = _overlap(qt, toks)
            if sc > 0.0:
                scored.append((q, a, sc))
        scored.sort(key=lambda p: p[2], reverse=True)
        return scored[:k]

    def count(self) -> int:
        self._load()
        return len(self._pairs)


def make_answer_fn(generate_fn: Optional[Callable[[str], str]] = None,
                   knowledge: Optional[KnowledgeRetrieval] = None,
                   memory: Optional[EpisodicStore] = None) -> Callable[[str], str]:
    """Local answer pipeline: retrieval-context + apna dimagh (generate_fn).

    generate_fn = Hemomemo ka apna composer (model.generate). Koi bhi
    bahar-ki AI yahan KABHI nahi lagti - agar na ho to retrieval-based
    jawab hi kaafi samjha diya jata hai (honest mode).
    """
    def answer(prompt: str) -> str:
        ctx_bits: List[str] = []
        if knowledge is not None:
            for q, a, _sc in knowledge.search(prompt, k=2):
                ctx_bits.append(a)
        if generate_fn is not None:
            try:
                out = generate_fn(prompt)
                if out and out.strip():
                    if ctx_bits:
                        return out.strip() + "\n\n" + ctx_bits[0][:400]
                    return out.strip()
            except Exception:
                pass
        if ctx_bits:
            return ctx_bits[0][:800]
        return ""
    return answer

"""HEMOMO REASONING - sochne ka loop (100% local, koi API nahi).

Input ko parhta hai -> irada pehchanta hai -> yaadasht + ilm nikalta hai
-> mansoora (plan) banata hai -> jawab-tayyar karta hai.

Ye LLM nahi hai - ye Hemomemo ka apna niyam-soch (rule + retrieval +
deterministic-math + local-LSTM composer) hai.
"""
from __future__ import annotations

import ast
import operator as op
import re
from dataclasses import dataclass, field
from typing import Callable, Dict, List, Optional, Tuple

# safe math evaluator (sirf calculator-ops, koi code-execute nahi)
_OPS = {ast.Add: op.add, ast.Sub: op.sub, ast.Mult: op.mul,
        ast.Div: op.truediv, ast.FloorDiv: op.floordiv,
        ast.Mod: op.mod, ast.Pow: op.pow, ast.USub: op.neg,
        ast.UAdd: op.pos}

def _ev(node):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
        return node.value
    if isinstance(node, ast.BinOp) and type(node.op) in _OPS:
        return _OPS[type(node.op)](_ev(node.left), _ev(node.right))
    if isinstance(node, ast.UnaryOp) and type(node.op) in _OPS:
        return _OPS[type(node.op)](_ev(node.operand))
    raise ValueError("unsupported")

def safe_math(expr: str) -> Optional[str]:
    """Sirf digits/operators wale maths ko pakka sahi jawab (deterministic)."""
    expr = expr.strip().replace("x", "*").replace("×", "*").replace("÷", "/")
    if not re.fullmatch(r"[\d\s\+\-\*/\(\)\.]+", expr):
        return None
    try:
        val = _ev(ast.parse(expr, mode="eval").body)
        if isinstance(val, float) and val.is_integer():
            val = int(val)
        return str(val)
    except Exception:
        return None


CODE_HINTS = ("python", "javascript", "java ", "kotlin", "c++", "cpp", "sql",
              "html", "css", "bash", "rust", "golang", "go ", "php", "ruby",
              "function", "class ", "loop", "array", "list", "api", "regex",
              "code", "program", "script", "bug", "error", "compile", "syntax")

GAME_HINTS = ("minecraft", "creeper", "enderman", "nether", "ender", "redstone",
              "biome", "mob", "spawn", "server", "game", "player", "roblox",
              "fortnite", "pokemon", "chess", "ludo", "speedrun", "mod", "skin")

ISLAMIC_HINTS = ("allah", "quran", "namaz", "salah", "roza", "sawm", "zakat",
                 "hajj", "umrah", "wudu", "ghusl", "hadith", "sunnah", "dua",
                 "ramadan", "eid", "tawheed", "sabr", "shukr", "hijab", "halal")

@dataclass
class Plan:
    intent: str
    steps: List[str] = field(default_factory=list)
    math_answer: Optional[str] = None
    context: List[str] = field(default_factory=list)
    final: str = ""


class Reasoner:
    """Hemomemo ka sochne-wala dimagh-module.

    answer_fn = Hemomemo ka local composer (injection se - testable).
    """

    def __init__(self, answer_fn: Optional[Callable[[str], str]] = None,
                 knowledge=None, memory=None) -> None:
        self.answer_fn = answer_fn
        self.knowledge = knowledge
        self.memory = memory

    # 1) irada pehchan
    def detect_intent(self, prompt: str) -> str:
        p = (prompt or "").lower()
        if safe_math(p):
            return "math"
        if any(h in p for h in ISLAMIC_HINTS):
            return "islamic"
        if any(h in p for h in CODE_HINTS):
            return "coding"
        if any(h in p for h in GAME_HINTS):
            return "game"
        return "general"

    # 2) context uthana (yaad + ilm)
    def gather(self, prompt: str) -> List[str]:
        ctx: List[str] = []
        if self.knowledge is not None:
            try:
                for _q, a, _s in self.knowledge.search(prompt, k=2):
                    ctx.append(a[:500])
            except Exception:
                pass
        if self.memory is not None:
            try:
                for rec in self.memory.recall(prompt, k=2):
                    ctx.append("pehle kaha: " + str(rec.get("user", ""))[:200])
            except Exception:
                pass
        return ctx

    # 3) mansoora banao
    def plan(self, prompt: str) -> Plan:
        intent = self.detect_intent(prompt)
        pl = Plan(intent=intent)
        pl.context = self.gather(prompt)
        if intent == "math":
            m = re.search(r"([\d\s\+\-\*x×÷/\(\)\.]+)", prompt)
            expr = m.group(1).strip() if m else prompt
            val = safe_math(expr)
            pl.math_answer = val
            pl.steps = ["math-expression parhi", "deterministic hisaab kiya",
                        "pakka jawab diya (guess nahi)"]
            pl.final = f"{expr} = {val}" if val is not None else ""
            return pl
        if intent == "coding":
            pl.steps = ["coding-sawal parha", "knowledge-retrieval se mutaliq code-ilm nikala",
                        "code-block jawab banaya (local)"]
        elif intent == "game":
            pl.steps = ["game-sawal parha (minecraft/games)",
                        "games-knowledge se mutaliq jawab nikala",
                        "agent-kheli style me jawab diya"]
        elif intent == "islamic":
            pl.steps = ["islami sawal parha", "adab ke sath, ilm ke dayre me jawab",
                        "yaqini-ilm ke ilawa ehtiyaat batayi"]
        else:
            pl.steps = ["sawal parha", "yaad+ilm se context jama kiya",
                        "apne dimagh se jawab banaya"]
        if self.answer_fn is not None:
            try:
                out = self.answer_fn(prompt)
                if out:
                    if pl.context:
                        pl.final = out.strip() + "\n\n" + pl.context[0][:400]
                    else:
                        pl.final = out.strip()
                    return pl
            except Exception:
                pass
        pl.final = (pl.context[0][:800] if pl.context else "")
        return pl

    # 4) seedha jawab
    def respond(self, prompt: str) -> str:
        pl = self.plan(prompt)
        return pl.final

    def respond_with_memory(self, prompt: str, tag: str = "chat") -> str:
        out = self.respond(prompt)
        if self.memory is not None and out:
            try:
                self.memory.remember(prompt, out, tag=tag)
            except Exception:
                pass
        return out

"""HEMOMO MINECRAFT BOT - apna local game-player (NO AI-API, kabhi nahi).

Kya karta hai:
  1) SERVER-MODE : offline-mode / LAN Minecraft server se judta hai
     (handshake -> login -> chat). Bot chat parhta/likhta hai aur
     Hemomemo ke apne dimagh se jawab deta hai (apna composer inject hota hai).
  2) DIRECT-MODE : bina server ke - aap terminal me type karo, bot
     Hemomemo ke dimagh se khelta-hua jawab deta hai (sath khelna).

Imandari-hadd (honest limits):
  - Encryption sirf online-mode (Mojang-auth) servers par chahiye hoti hai -
    wo BAHAR ka auth hai, is liye support NAHI (offline/LAN servers ok).
  - Block-level khel (dig/build) ke liye server-side plugin (jaise mcpi /
    Raspberry-Jam) chahiye hota hai - wo hook neeche OPTIONAL diya gaya hai.

Ye file kisi bhi waqt koi bahar-ki-AI se baat NAHI karti - sirf
aap ke PC ka socket (server se khelne ke liye) aur aap ka terminal.
"""
from __future__ import annotations

import json
import socket
import struct
import sys
import threading
import time
from typing import Callable, Optional

# --- Minecraft protocol version (client khud batata hai) ---
PROTOCOL_VERSION = 763  # 1.20.1 (badal sakte hain: 767=1.21 etc.)

STATE_STATUS = 1
STATE_LOGIN = 2
STATE_PLAY = 3


# ---------------- VarInt / framing ----------------
def write_varint(value: int) -> bytes:
    out = bytearray()
    while True:
        b = value & 0x7F
        value >>= 7
        if value:
            out.append(b | 0x80)
        else:
            out.append(b)
            return bytes(out)


def read_varint(sock: socket.socket) -> Optional[int]:
    num = 0
    for i in range(5):
        chunk = sock.recv(1)
        if not chunk:
            return None
        b = chunk[0]
        num |= (b & 0x7F) << (7 * i)
        if not (b & 0x80):
            break
    return num


def pack_packet(packet_id: int, payload: bytes) -> bytes:
    body = write_varint(packet_id) + payload
    return write_varint(len(body)) + body


def unpack_packet(sock: socket.socket):
    """(packet_id, payload) ya None."""
    length = read_varint(sock)
    if not length or length > 2_000_000:
        return None
    data = b""
    while len(data) < length:
        chunk = sock.recv(length - len(data))
        if not chunk:
            return None
        data += chunk
    # packet-id varint parho
    pid = 0
    shift = 0
    idx = 0
    while True:
        b = data[idx]
        pid |= (b & 0x7F) << shift
        idx += 1
        if not (b & 0x80):
            break
        shift += 7
    return pid, data[idx:]


def _mc_string(s: str) -> bytes:
    raw = s.encode("utf-8")
    return write_varint(len(raw)) + raw


def _read_mc_string(payload: bytes) -> str:
    ln = 0
    shift = 0
    idx = 0
    while True:
        b = payload[idx]
        ln |= (b & 0x7F) << shift
        idx += 1
        if not (b & 0x80):
            break
        shift += 7
    return payload[idx:idx + ln].decode("utf-8", errors="replace")


# ---------------- Bot ----------------
class MinecraftBot:
    """Hemomemo ka game-player bot (100% local brain).

    answer_fn = Hemomemo ka apna jawab-dene-wala (model.reasoning Reasoner).
    """

    def __init__(self, answer_fn: Callable[[str], str],
                 username: str = "HemomemoAI",
                 protocol_version: int = PROTOCOL_VERSION,
                 verbose: bool = True) -> None:
        self.answer_fn = answer_fn
        self.username = username
        self.protocol_version = protocol_version
        self.verbose = verbose
        self.sock: Optional[socket.socket] = None
        self.running = False
        self._thread: Optional[threading.Thread] = None
        self._pending_keepalive = 0

    # --- log ---
    def _log(self, msg: str) -> None:
        if self.verbose:
            print("[hemomemo-bot] " + msg, flush=True)

    # --- 1) server se judna ---
    def join_server(self, host: str, port: int = 25565, timeout: float = 8.0) -> bool:
        try:
            self.sock = socket.create_connection((host, port), timeout=timeout)
            self.sock.settimeout(0.5)  # non-blocking-ish read loop
        except OSError as e:
            self._log(f"server-judna fail: {e}")
            self.sock = None
            return False
        # handshake: ver | host | port | next-state=login
        hs = (write_varint(self.protocol_version) + _mc_string(host)
              + struct.pack(">H", port) + write_varint(STATE_LOGIN))
        self.sock.sendall(pack_packet(0x00, hs))
        # login start: username
        self.sock.sendall(pack_packet(0x00, _mc_string(self.username)))
        self._log(f"login bheja: {self.username} -> {host}:{port}")
        # login success (0x02) ya disconnect (0x00) ka intezar (thodi der)
        t0 = time.time()
        while time.time() - t0 < timeout:
            pkt = unpack_packet(self.sock)
            if pkt is None:
                continue
            pid, payload = pkt
            if pid == 0x02:  # login success
                self._log("server ne login qubool kar liya - khel shuru!")
                return True
            if pid == 0x00:  # disconnect (login-phase)
                self._log("server ne mana kiya: " + _read_mc_string(payload)[:200])
                return False
        self._log("login-waqt khatam")
        return False

    # --- 2) chat bhejna (play-state) ---
    def say(self, msg: str) -> bool:
        if not self.sock:
            return False
        try:
            self.sock.sendall(pack_packet(0x05, _mc_string(msg[:256])))  # 0x05=chat (1.20.x)
            return True
        except OSError:
            return False

    # --- 3) sun'na + Hemomemo-dimagh se jawab ---
    def _handle_play(self, pid: int, payload: bytes) -> None:
        if pid == 0x0F:  # keepalive (1.20.x) -> wapas bhejo
            if len(payload) >= 8:
                self.sock.sendall(pack_packet(0x0F, payload[:8]))  # echo same id
            return
        if pid == 0x30:  # system/chat message (1.20.x)
            try:
                text = _read_mc_string(payload)
                self._on_chat(text)
            except Exception:
                pass
            return

    def _on_chat(self, raw: str) -> None:
        self._log("chat: " + raw[:200])
        # bot ko address kiya gaya? (Hemomemo / hemomemo / @bot)
        low = raw.lower()
        if "hemomemo" in low or self.username.lower() in low:
            sawal = raw
            for token in ("<", ">", "[", "]"):
                sawal = sawal.replace(token, " ")
            jawab = ""
            try:
                jawab = (self.answer_fn(sawal.strip()) or "").strip()
            except Exception:
                jawab = ""
            if not jawab:
                jawab = "Main Hemomemo AI hoon - 100% local. Batao kis game me madad karoon?"
            self.say(jawab[:250])

    def _loop(self) -> None:
        while self.running and self.sock:
            try:
                pkt = unpack_packet(self.sock)
                if pkt:
                    self._handle_play(*pkt)
            except socket.timeout:
                continue
            except OSError:
                break

    # --- 4) khelna shuru (background sun'na) ---
    def play(self) -> None:
        if not self.sock:
            self._log("pehle join_server() chalao")
            return
        self.running = True
        self.say(f"Assalam-o-alaikum! Main {self.username} hoon - Hemomemo AI (100% local).")
        self._thread = threading.Thread(target=self._loop, daemon=True)
        self._thread.start()

    def leave(self) -> None:
        self.running = False
        try:
            if self.sock:
                self.sock.close()
        except OSError:
            pass
        self._log("server chhoda")

    # --- 5) OPTIONAL: mcpi hook (block-level khel, agar mojood ho) ---
    def try_mcpi(self, host: str = "localhost") -> bool:
        """Raspberry-Jam/mcpi style local API (agar Minecraft me plugin ho)."""
        try:
            from mcpi.minecraft import Minecraft  # type: ignore
            mc = Minecraft.create(address=host)
            mc.postToChat("Hemomemo AI jud gaya - 100% local dimagh!")
            self._log("mcpi hook chal - block-level khel mumkin")
            return True
        except Exception:
            self._log("mcpi nahi mila (optional hai) - chat-mode kaafi hai")
            return False


def direct_play(answer_fn: Callable[[str], str], bot_name: str = "HemomemoAI") -> None:
    """DIRECT-MODE: bina server ke - aap type karo, bot sath khelta hai."""
    print(f"=== {bot_name} DIRECT-PLAY (100% local) - 'khatam' likh kar band karo ===")
    hist: list = []
    while True:
        try:
            q = input("aap> ").strip()
        except (EOFError, KeyboardInterrupt):
            break
        if not q:
            continue
        if q.lower() in ("khatam", "quit", "exit"):
            break
        jawab = answer_fn(q)
        if not jawab:
            jawab = "(dimagh soch raha hai - thora aur wazah sawal do)"
        print(f"{bot_name}> {jawab[:500]}")
        hist.append((q, jawab[:120]))
    print(f"direct-play khatam - {len(hist)} baatein yaad mein mehfooz hain.")


