def _math(self, u: tk.Understanding) -> Optional[str]:
    """Saada arithmetic (2+2, 9*5+9*4) - deterministic."""
    m = re.search(r"[\d][\d\s\+\-\*x/^().]*[\d\)]", u.text)
    if not m:
        return None
    expr = m.group(0).replace("^", "**").replace("x", "*")
    val = safe_math(expr)
    if val is None:
        return None
    steps = expr.replace("**", "^")
    return "hisab: %s = %s" % (steps, val)

