            social = social or "greet"
            bases.append("greet:" + w)
        elif w in ("good", "morning", "evening", "night", "afternoon"):
            social = social or "greet"
            bases.append("greet-time:" + w)
        else:
            for name, rx in _SOCIAL_CALL.items():
                if rx.match(w):
                    if social is None:
