// find npm / openai-compatible / custom provider mentions
const out = [];
for (const term of ["openai-compatible", "npm", "Custom provider", "custom", "config.json", "baseURL", "env:"]) {
  let idx = 0, n = 0;
  const needle = term;
  while (n < 6) {
    const i = md.indexOf(needle, idx);
    if (i < 0) break;
    out.push("[" + term + "] " + md.slice(Math.max(0, i - 150), i + 200).replace(/\s+/g, " "));
    idx = i + needle.length; n++;
  }
}
return out.join("\n---\n");

